body:
### Description

The account_data and ephemeral events are not returned then when specifying a the "rooms" property of a RoomFilter while calling the /sync api endpoint

### Steps to reproduce

- GET https://b/_matrix/client/r0/sync?filter=###see below###
```
{
  "room": {
  	"rooms": ["!a:b"]
  },
  "presence": {
    "types": []
  },
  "account_data": {
    "types": []
  }
}
```

#### Expected Response

This is what get returned when you perform the same call with no rooms filter. I've manually truncated the events for the timeline and state events as they are not relevant (working as intended)

```
{
    "account_data": {
        "events": []
    },
    "to_device": {
        "events": []
    },
    "device_lists": {
        "changed": [],
        "left": []
    },
    "presence": {
        "events": []
    },
    "rooms": {
        "join": {
            "!a:b": {
                "timeline": {
                    "events": [...],
                    "prev_batch": "t95-5277_30156_0_511_6316_1_1_166_1",
                    "limited": true
                },
                "state": {
                    "events": [...]
                },
                "account_data": {
                    "events": [
                        {
                            "type": "m.fully_read",
                            "content": {
                                "event_id": "$m7zauVBF6pd9C1BBExtPgWWkWCXoGRoheBm4EzokiY4"
                            }
                        }
                    ]
                },
                "ephemeral": {
                    "events": [
                        {
                            "type": "m.receipt",
                            "content": {
                                "$V9G8_p1otbFb7sXCl9xxBUQ8S_x-NTU8RswSu5HypNs": {
                                    "m.read": {
                                        "@user1:b": {
                                            "ts": 1605183844082
                                        }
                                    }
                                },
                                "$DCUMbQjC6oK5WPQaMx75-lFog3WlF3t781tRwZoQFwU": {
                                    "m.read": {
                                        "@user2:b": {
                                            "ts": 1604571555681
                                        }
                                    }
                                },
                                "$m7zauVBF6pd9C1BBExtPgWWkWCXoGRoheBm4EzokiY4": {
                                    "m.read": {
                                        "user3:b": {
                                            "ts": 1604575454389
                                        }
                                    }
                                }
                            }
                        }
                    ]
                },
                "unread_notifications": {
                    "notification_count": 0,
                    "highlight_count": 0
                },
                "summary": {},
                "org.matrix.msc2654.unread_count": 0
            }
        },
        "invite": {},
        "leave": {}
    },
    "groups": {
        "join": {},
        "invite": {},
        "leave": {}
    },
    "device_one_time_keys_count": {},
    "org.matrix.msc2732.device_unused_fallback_key_types": [],
    "next_batch": "s5287_30156_0_511_6316_1_1_166_1"
}
```

#### Received Response

```
{
    "account_data": {
        "events": []
    },
    "to_device": {
        "events": []
    },
    "device_lists": {
        "changed": [],
        "left": []
    },
    "presence": {
        "events": []
    },
    "rooms": {
        "join": {
            "!a:b": {
                "timeline": {
                    "events": [...],
                    "prev_batch": "t95-5277_30156_0_511_6316_1_1_166_1",
                    "limited": true
                },
                "state": {
                    "events": [...]
                },
                "account_data": {
                    "events": []
                },
                "ephemeral": {
                    "events": []
                },
                "unread_notifications": {
                    "notification_count": 0,
                    "highlight_count": 0
                },
                "summary": {},
                "org.matrix.msc2654.unread_count": 0
            }
        },
        "invite": {},
        "leave": {}
    },
    "groups": {
        "join": {},
        "invite": {},
        "leave": {}
    },
    "device_one_time_keys_count": {},
    "org.matrix.msc2732.device_unused_fallback_key_types": [],
    "next_batch": "s5287_30156_0_511_6316_1_1_166_1"
}
```

### Version information
- **Homeserver**:  Local development home server
- **Version**: 1.20.1, 1.22.1 (tried upgrading, but it had no effect)
- **Install method**: Helm chart (https://github.com/dacruz21/matrix-chart)

- **Platform**: Running on kubernetes 1.19 using the matrixdotorg/synapse:v1.22.1 docker container
